import torch, b200probe as bp, inspect
print(inspect.signature(bp.cuda_kernel)); print(inspect.signature(bp.harness_time))
print(bp.harness_time.__doc__); print(bp.cuda_kernel.__doc__)
src = r'''
#include <cuda_runtime.h>
struct __align__(32) f8 { float4 a, b; };
extern "C" __global__ void __launch_bounds__(256)
rms_v1(const float* __restrict__ q, const float* __restrict__ k,
       const float* __restrict__ wq, const float* __restrict__ wk,
       float* __restrict__ oq, float* __restrict__ ok, float eps, long nrows)
{
    // half-warp per row, 8 floats per thread (256-bit), rows of Q then rows of K
    long gt = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long row = gt >> 4;            // 16 threads per row
    int lane = threadIdx.x & 15;
    const float* x; const float* w; float* o;
    if (row < nrows) { x = q; w = wq; o = oq; }
    else { row -= nrows; if (row >= nrows) return; x = k; w = wk; o = ok; }
    int head = (int)(row % 48);
    const f8* xp = reinterpret_cast<const f8*>(x + row * 128) + lane;
    const f8* wp = reinterpret_cast<const f8*>(w + head * 128) + lane;
    f8 v = *xp;
    f8 ww = __ldg(wp);
    float s = v.a.x*v.a.x + v.a.y*v.a.y + v.a.z*v.a.z + v.a.w*v.a.w
            + v.b.x*v.b.x + v.b.y*v.b.y + v.b.z*v.b.z + v.b.w*v.b.w;
    s += __shfl_xor_sync(0xffffffff, s, 1);
    s += __shfl_xor_sync(0xffffffff, s, 2);
    s += __shfl_xor_sync(0xffffffff, s, 4);
    s += __shfl_xor_sync(0xffffffff, s, 8);
    float r = rsqrtf(s * (1.0f/128.0f) + eps);
    f8 out;
    out.a.x = v.a.x*r*ww.a.x; out.a.y = v.a.y*r*ww.a.y; out.a.z = v.a.z*r*ww.a.z; out.a.w = v.a.w*r*ww.a.w;
    out.b.x = v.b.x*r*ww.b.x; out.b.y = v.b.y*r*ww.b.y; out.b.z = v.b.z*r*ww.b.z; out.b.w = v.b.w*r*ww.b.w;
    *(reinterpret_cast<f8*>(o + row * 128) + lane) = out;
}
'''
k = bp.cuda_kernel(src, "rms_v1")
print(bp.resources(src))
s = bp.sass(src)
import re
print(sorted(set(re.findall(r'(LDG\.[A-Z0-9\.]+|STG\.[A-Z0-9\.]+)', s))))
shapes = [(1,128),(1,131),(2,128),(2,293),(8,128),(4,512),(4,1024),(8,773),(1,8192)]
def ref(q,k,wq,wk,eps):
    qv = q.pow(2).mean(-1, keepdim=True); kv = k.pow(2).mean(-1, keepdim=True)
    return (q*torch.rsqrt(qv+eps))*wq, (k*torch.rsqrt(kv+eps))*wk
for B,S in shapes:
    q = torch.randn(B,S,48,128, device='cuda'); kk = torch.randn_like(q)
    wq = torch.randn(48,128, device='cuda'); wk = torch.randn_like(wq)
    oq = torch.empty_like(q); ok = torch.empty_like(q)
    n = B*S*48
    def fn(q,kk,wq,wk,oq,ok):
        thr = 256; total = 2*n*16
        k(((total+thr-1)//thr,1,1),(thr,1,1), q,kk,wq,wk,oq,ok, 1e-6, n)
    fn(q,kk,wq,wk,oq,ok); torch.cuda.synchronize()
    rq, rk = ref(q,kk,wq,wk,1e-6)
    err = max((oq-rq).abs().max().item(), (ok-rk).abs().max().item())
    t = bp.harness_time(fn, [q,kk,wq,wk], [oq,ok])
    mb = 2*2*n*512/1e6
    print(f"B={B} S={S} MB={mb:.1f} t={t:.2f}us  {mb/t*1e-3:.2f} TB/s  maxerr={err:.2e}")

