import torch, b200probe as bp, re
tmpl = r'''
#include <cuda_runtime.h>
struct __align__(32) f8 { float4 a, b; };
__device__ __forceinline__ f8 ldx(const f8* p) {
    f8 v;
#if LDHINT==1
    asm volatile("ld.global.L1::no_allocate.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
        : "=f"(v.a.x),"=f"(v.a.y),"=f"(v.a.z),"=f"(v.a.w),"=f"(v.b.x),"=f"(v.b.y),"=f"(v.b.z),"=f"(v.b.w) : "l"(p));
#elif LDHINT==2
    asm volatile("ld.global.L2::evict_first.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
        : "=f"(v.a.x),"=f"(v.a.y),"=f"(v.a.z),"=f"(v.a.w),"=f"(v.b.x),"=f"(v.b.y),"=f"(v.b.z),"=f"(v.b.w) : "l"(p));
#elif LDHINT==3
    asm volatile("ld.global.L1::no_allocate.L2::evict_first.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
        : "=f"(v.a.x),"=f"(v.a.y),"=f"(v.a.z),"=f"(v.a.w),"=f"(v.b.x),"=f"(v.b.y),"=f"(v.b.z),"=f"(v.b.w) : "l"(p));
#else
    v = *p;
#endif
    return v;
}
__device__ __forceinline__ void stx(f8* p, f8 v) {
#if STHINT==1
    asm volatile("st.global.cs.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};" :: "l"(p),
        "f"(v.a.x),"f"(v.a.y),"f"(v.a.z),"f"(v.a.w),"f"(v.b.x),"f"(v.b.y),"f"(v.b.z),"f"(v.b.w) : "memory");
#elif STHINT==2
    asm volatile("st.global.L2::evict_first.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};" :: "l"(p),
        "f"(v.a.x),"f"(v.a.y),"f"(v.a.z),"f"(v.a.w),"f"(v.b.x),"f"(v.b.y),"f"(v.b.z),"f"(v.b.w) : "memory");
#elif STHINT==3
    asm volatile("st.global.L1::no_allocate.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};" :: "l"(p),
        "f"(v.a.x),"f"(v.a.y),"f"(v.a.z),"f"(v.a.w),"f"(v.b.x),"f"(v.b.y),"f"(v.b.z),"f"(v.b.w) : "memory");
#else
    *p = v;
#endif
}
__device__ __forceinline__ void one(const f8* xp, const f8* wp, f8* op, float eps) {
    f8 v = ldx(xp); f8 ww = *wp;
    float s = v.a.x*v.a.x + v.a.y*v.a.y + v.a.z*v.a.z + v.a.w*v.a.w + v.b.x*v.b.x + v.b.y*v.b.y + v.b.z*v.b.z + v.b.w*v.b.w;
    s += __shfl_xor_sync(0xffffffff, s, 1); s += __shfl_xor_sync(0xffffffff, s, 2);
    s += __shfl_xor_sync(0xffffffff, s, 4); s += __shfl_xor_sync(0xffffffff, s, 8);
    float r = rsqrtf(s * (1.0f/128.0f) + eps);
    f8 o;
    o.a.x = v.a.x*r*ww.a.x; o.a.y = v.a.y*r*ww.a.y; o.a.z = v.a.z*r*ww.a.z; o.a.w = v.a.w*r*ww.a.w;
    o.b.x = v.b.x*r*ww.b.x; o.b.y = v.b.y*r*ww.b.y; o.b.z = v.b.z*r*ww.b.z; o.b.w = v.b.w*r*ww.b.w;
    stx(op, o);
}
extern "C" __global__ void __launch_bounds__(THR)
kern(const float* __restrict__ q, const float* __restrict__ k, const float* __restrict__ wq, const float* __restrict__ wk,
     float* __restrict__ oq, float* __restrict__ ok, float eps, long nrows)
{
    // RPT rows per thread-group: thread handles RPT rows spaced by (blockDim/16) rows
    long rows_per_cta = (long)(THR/16) * RPT;
    long base = (long)blockIdx.x * rows_per_cta + (threadIdx.x >> 4);
    int lane = threadIdx.x & 15;
    const f8* xp[RPT]; const f8* wp[RPT]; f8* op[RPT]; bool ok_[RPT];
    #pragma unroll
    for (int i = 0; i < RPT; i++) {
        long row = base + (long)i * (THR/16);
        const float* x; const float* w; float* o;
        ok_[i] = true;
        if (row < nrows) { x = q; w = wq; o = oq; }
        else { row -= nrows; if (row >= nrows) { ok_[i] = false; row = 0; } x = k; w = wk; o = ok; }
        int head = (int)(row % 48);
        xp[i] = reinterpret_cast<const f8*>(x + row * 128) + lane;
        wp[i] = reinterpret_cast<const f8*>(w + head * 128) + lane;
        op[i] = reinterpret_cast<f8*>(o + row * 128) + lane;
    }
    f8 v[RPT];
    #pragma unroll
    for (int i = 0; i < RPT; i++) if (ok_[i]) v[i] = ldx(xp[i]);
    #pragma unroll
    for (int i = 0; i < RPT; i++) if (ok_[i]) {
        f8 ww = *wp[i];
        float s = v[i].a.x*v[i].a.x + v[i].a.y*v[i].a.y + v[i].a.z*v[i].a.z + v[i].a.w*v[i].a.w + v[i].b.x*v[i].b.x + v[i].b.y*v[i].b.y + v[i].b.z*v[i].b.z + v[i].b.w*v[i].b.w;
        s += __shfl_xor_sync(0xffffffff, s, 1); s += __shfl_xor_sync(0xffffffff, s, 2);
        s += __shfl_xor_sync(0xffffffff, s, 4); s += __shfl_xor_sync(0xffffffff, s, 8);
        float r = rsqrtf(s * (1.0f/128.0f) + eps);
        f8 o;
        o.a.x = v[i].a.x*r*ww.a.x; o.a.y = v[i].a.y*r*ww.a.y; o.a.z = v[i].a.z*r*ww.a.z; o.a.w = v[i].a.w*r*ww.a.w;
        o.b.x = v[i].b.x*r*ww.b.x; o.b.y = v[i].b.y*r*ww.b.y; o.b.z = v[i].b.z*r*ww.b.z; o.b.w = v[i].b.w*r*ww.b.w;
        stx(op[i], o);
    }
}
'''
def build(THR, RPT, LD, ST):
    src = f"#define THR {THR}\n#define RPT {RPT}\n#define LDHINT {LD}\n#define STHINT {ST}\n" + tmpl
    try:
        k = bp.cuda_kernel(src, "kern")
    except Exception as e:
        print("FAIL", THR,RPT,LD,ST, str(e)[-300:]); return None
    regs = re.search(r'REG:(\d+)', bp.resources(src)).group(1)
    return k, regs
shapes = [(1,128),(2,293),(8,128),(4,1024),(1,8192)]
data = {}
for B,S in shapes:
    q = torch.randn(B,S,48,128, device='cuda'); kk = torch.randn_like(q)
    wq = torch.randn(48,128, device='cuda'); wk = torch.randn_like(wq)
    data[(B,S)] = (q,kk,wq,wk,torch.empty_like(q),torch.empty_like(q))
configs = [(256,1,0,0),(256,2,0,0),(256,4,0,0),(128,2,0,0),(512,1,0,0),(1024,1,0,0),
           (256,1,1,0),(256,1,2,0),(256,1,3,0),(256,1,0,1),(256,1,0,2),(256,1,0,3),(256,2,3,2)]
for cfg in configs:
    r = build(*cfg)
    if r is None: continue
    k, regs = r
    THR,RPT = cfg[0],cfg[1]
    line = f"THR={THR} RPT={RPT} LD={cfg[2]} ST={cfg[3]} regs={regs}:"
    for (B,S),(q,kk,wq,wk,oq,ok) in data.items():
        n = B*S*48
        rows_per_cta = (THR//16)*RPT
        grid = (2*n + rows_per_cta - 1)//rows_per_cta
        def fn(q,kk,wq,wk,oq,ok): k((grid,1,1),(THR,1,1), q,kk,wq,wk,oq,ok,1e-6,n)
        fn(q,kk,wq,wk,oq,ok); torch.cuda.synchronize()
        rq = (q*torch.rsqrt(q.pow(2).mean(-1,keepdim=True)+1e-6))*wq
        rk = (kk*torch.rsqrt(kk.pow(2).mean(-1,keepdim=True)+1e-6))*wk
        bad = not (torch.allclose(oq,rq,atol=1e-5,rtol=1e-5) and torch.allclose(ok,rk,atol=1e-5,rtol=1e-5))
        t = bp.harness_time(fn, [q,kk,wq,wk], [oq,ok])
        line += f"  {B}x{S}: {t:.2f}{'!' if bad else ''}"
    print(line)

import torch, b200probe as bp, re
src = r'''
#include <cuda_runtime.h>
struct __align__(32) f8 { float4 a, b; };
extern "C" __global__ void __launch_bounds__(256) empty_k(const float* q, const float* k, float* oq, float* ok, long nrows) { }
extern "C" __global__ void __launch_bounds__(256) read_k(const float* __restrict__ q, const float* __restrict__ k, float* __restrict__ oq, float* __restrict__ ok, long nrows) {
    long gt = (long)blockIdx.x * blockDim.x + threadIdx.x; long row = gt >> 4; int lane = threadIdx.x & 15;
    const float* x; float* o;
    if (row < nrows) { x = q; o = oq; } else { row -= nrows; if (row >= nrows) return; x = k; o = ok; }
    f8 v = *(reinterpret_cast<const f8*>(x + row*128) + lane);
    float s = v.a.x+v.a.y+v.a.z+v.a.w+v.b.x+v.b.y+v.b.z+v.b.w;
    if (s == 123456.0f) o[row*128+lane] = s;   // practically never
}
extern "C" __global__ void __launch_bounds__(256) write_k(const float* __restrict__ q, const float* __restrict__ k, float* __restrict__ oq, float* __restrict__ ok, long nrows) {
    long gt = (long)blockIdx.x * blockDim.x + threadIdx.x; long row = gt >> 4; int lane = threadIdx.x & 15;
    float* o;
    if (row < nrows) { o = oq; } else { row -= nrows; if (row >= nrows) return; o = ok; }
    f8 v; v.a = make_float4(1,2,3,4); v.b = make_float4(5,6,7,8);
    *(reinterpret_cast<f8*>(o + row*128) + lane) = v;
}
extern "C" __global__ void __launch_bounds__(256) oneline_k(const float* __restrict__ q, const float* __restrict__ k, float* __restrict__ oq, float* __restrict__ ok, long nrows) {
    // each CTA: thread 0 reads one float and writes one float
    if (threadIdx.x == 0) { float v = q[(long)blockIdx.x * 32]; oq[(long)blockIdx.x*32] = v; }
}
'''
ks = {n: bp.cuda_kernel(src, n) for n in ["empty_k","read_k","write_k","oneline_k"]}
for B,S in [(1,128),(1,8192)]:
    q = torch.randn(B,S,48,128, device='cuda'); kk = torch.randn_like(q); oq = torch.empty_like(q); ok = torch.empty_like(q)
    n = B*S*48; grid = (2*n*16 + 255)//256
    for name, g in [("empty_k", grid), ("empty_k1", 1), ("empty_k148", 148), ("oneline_k", 148), ("oneline_k1184", 1184), ("read_k", grid), ("write_k", grid)]:
        k = ks[name.rstrip('0123456789')]
        def fn(q,kk,oq,ok): k((g,1,1),(256,1,1), q,kk,oq,ok,n)
        t = bp.harness_time(fn, [q,kk], [oq,ok])
        print(f"{B}x{S} {name:14s} grid={g:6d}: {t:.2f} us")

import torch, b200probe as bp, statistics
src = r'''
#include <cuda_runtime.h>
struct __align__(32) f8 { float4 a, b; };
extern "C" __global__ void __launch_bounds__(256) read_k(const float* __restrict__ q, const float* __restrict__ k, float* __restrict__ oq, float* __restrict__ ok, long nrows) {
    long gt = (long)blockIdx.x * blockDim.x + threadIdx.x; long row = gt >> 4; int lane = threadIdx.x & 15;
    const float* x; float* o;
    if (row < nrows) { x = q; o = oq; } else { row -= nrows; if (row >= nrows) return; x = k; o = ok; }
    f8 v = *(reinterpret_cast<const f8*>(x + row*128) + lane);
    float s = v.a.x+v.a.y+v.a.z+v.a.w+v.b.x+v.b.y+v.b.z+v.b.w;
    if (s == 123456.0f) o[row*128+lane] = s;
}
extern "C" __global__ void __launch_bounds__(256) full_k(const float* __restrict__ q, const float* __restrict__ k, float* __restrict__ oq, float* __restrict__ ok, long nrows) {
    long gt = (long)blockIdx.x * blockDim.x + threadIdx.x; long row = gt >> 4; int lane = threadIdx.x & 15;
    const float* x; float* o;
    if (row < nrows) { x = q; o = oq; } else { row -= nrows; if (row >= nrows) return; x = k; o = ok; }
    f8 v = *(reinterpret_cast<const f8*>(x + row*128) + lane);
    float s = v.a.x*v.a.x+v.a.y*v.a.y+v.a.z*v.a.z+v.a.w*v.a.w+v.b.x*v.b.x+v.b.y*v.b.y+v.b.z*v.b.z+v.b.w*v.b.w;
    s += __shfl_xor_sync(0xffffffff, s, 1); s += __shfl_xor_sync(0xffffffff, s, 2);
    s += __shfl_xor_sync(0xffffffff, s, 4); s += __shfl_xor_sync(0xffffffff, s, 8);
    float r = rsqrtf(s/128.f + 1e-6f);
    v.a.x*=r; v.a.y*=r; v.a.z*=r; v.a.w*=r; v.b.x*=r; v.b.y*=r; v.b.z*=r; v.b.w*=r;
    *(reinterpret_cast<f8*>(o + row*128) + lane) = v;
}
extern "C" __global__ void empty_k(const float* q, const float* k, float* oq, float* ok, long nrows) {}
'''
ks = {n: bp.cuda_kernel(src, n) for n in ["read_k","full_k","empty_k"]}
L2 = 126*2**20
buf = torch.empty(2*L2//4, device='cuda', dtype=torch.float32)
def flush_dirty(): buf.zero_()
def flush_clean(): buf.sum()
def ev_time(fn, flush, rep=30):
    ts=[]
    for i in range(rep):
        flush(); torch.cuda.synchronize()
        s=torch.cuda.Event(enable_timing=True); e=torch.cuda.Event(enable_timing=True)
        s.record(); fn(); e.record(); torch.cuda.synchronize(); ts.append(s.elapsed_time(e)*1000)
    return statistics.median(ts)
for B,S in [(1,128),(2,293),(8,128),(1,8192)]:
    q = torch.randn(B,S,48,128, device='cuda'); kk = torch.randn_like(q); oq = torch.empty_like(q); ok = torch.empty_like(q)
    n = B*S*48; grid = (2*n*16 + 255)//256
    for name in ["empty_k","read_k","full_k"]:
        k = ks[name]
        fn = lambda: k((grid,1,1),(256,1,1), q,kk,oq,ok,n)
        td = ev_time(fn, flush_dirty); tc = ev_time(fn, flush_clean); tn = ev_time(fn, lambda: None)
        print(f"{B}x{S} {name:8s} dirty-L2 {td:7.2f}  clean-L2 {tc:7.2f}  warm {tn:7.2f} us (event timing)")

