import torch, b200probe as bp, time
def ref(query, key, weight_q, weight_k, eps):
    qv = query.pow(2).mean(dim=-1, keepdim=True); qn = query*torch.rsqrt(qv+eps)
    kv = key.pow(2).mean(dim=-1, keepdim=True); kn = key*torch.rsqrt(kv+eps)
    return qn*weight_q.unsqueeze(0).unsqueeze(0), kn*weight_k.unsqueeze(0).unsqueeze(0)
try:
    t0=time.time(); cref = torch.compile(ref, dynamic=True); 
    for B,S in [(1,128),(2,293),(8,128),(4,1024),(1,8192)]:
        q = torch.randn(B,S,48,128, device='cuda'); kk = torch.randn_like(q)
        wq = torch.randn(48,128, device='cuda'); wk = torch.randn_like(wq)
        oq = torch.empty_like(q); ok = torch.empty_like(q)
        def fn(q,kk,wq,wk,oq,ok):
            a,b = cref(q,kk,wq,wk,1e-6); oq.copy_(a); ok.copy_(b)
        def fn2(q,kk,wq,wk,oq,ok):
            cref(q,kk,wq,wk,1e-6)
        fn(q,kk,wq,wk,oq,ok); torch.cuda.synchronize()
        t = bp.harness_time(fn2, [q,kk,wq,wk], [oq,ok]); tr = bp.harness_time(lambda *a: ref(q,kk,wq,wk,1e-6), [q,kk,wq,wk], [oq,ok])
        print(f"torch.compile {B}x{S}: {t:.2f} us (no output copy)   eager ref {tr:.1f} us")
    print("compile wall", time.time()-t0)
except Exception as e:
    print("torch.compile failed:", repr(e)[:800])

