ksrc = r'''
#include <cuda_runtime.h>
struct __align__(32) f8 { float4 a, b; };
extern "C" __global__ void empty0() {}
extern "C" __global__ void empty8(const float* q, const float* k, const float* wq, const float* wk, float* oq, float* ok, float eps, long nrows) {}
extern "C" __global__ void __launch_bounds__(256) write_el(const float* __restrict__ q, const float* __restrict__ k, float* __restrict__ oq, float* __restrict__ ok, long nrows) {
    long gt = (long)blockIdx.x * blockDim.x + threadIdx.x; long row = gt >> 4; int lane = threadIdx.x & 15;
    float* o;
    if (row < nrows) { o = oq; } else { row -= nrows; if (row >= nrows) return; o = ok; }
    f8 v; v.a = make_float4(1,2,3,4); v.b = make_float4(5,6,7,8);
    f8* p = reinterpret_cast<f8*>(o + row*128) + lane;
    asm volatile("st.global.L2::evict_last.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};" :: "l"(p), "f"(v.a.x),"f"(v.a.y),"f"(v.a.z),"f"(v.a.w),"f"(v.b.x),"f"(v.b.y),"f"(v.b.z),"f"(v.b.w) : "memory");
}
extern "C" __global__ void __launch_bounds__(256) read_ef(const float* __restrict__ q, const float* __restrict__ k, float* __restrict__ oq, float* __restrict__ ok, long nrows) {
    long gt = (long)blockIdx.x * blockDim.x + threadIdx.x; long row = gt >> 4; int lane = threadIdx.x & 15;
    const float* x; float* o;
    if (row < nrows) { x = q; o = oq; } else { row -= nrows; if (row >= nrows) return; x = k; o = ok; }
    const f8* p = reinterpret_cast<const f8*>(x + row*128) + lane; f8 v;
    asm volatile("ld.global.L2::evict_first.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(v.a.x),"=f"(v.a.y),"=f"(v.a.z),"=f"(v.a.w),"=f"(v.b.x),"=f"(v.b.y),"=f"(v.b.z),"=f"(v.b.w) : "l"(p));
    float s = v.a.x+v.a.y+v.a.z+v.a.w+v.b.x+v.b.y+v.b.z+v.b.w;
    if (s == 123456.0f) o[row*128+lane] = s;
}
