    t8 = bp.harness_time(lambda q,kk,oq,ok: ks["empty8"]((grid,1,1),(256,1,1), q,kk,q,kk,oq,ok,1e-6,n), [q,kk], [oq,ok])
    tw = bp.harness_time(lambda q,kk,oq,ok: ks["write_el"]((grid,1,1),(256,1,1), q,kk,oq,ok,n), [q,kk], [oq,ok])
    tr = bp.harness_time(lambda q,kk,oq,ok: ks["read_ef"]((grid,1,1),(256,1,1), q,kk,oq,ok,n), [q,kk], [oq,ok])
    print(f"{B}x{S}: empty0 {t0:.2f}  empty8 {t8:.2f}  write_el {tw:.2f}  read_ef {tr:.2f} us")

