    oo.a.x=v.a.x*r*ww.a.x; oo.a.y=v.a.y*r*ww.a.y; oo.a.z=v.a.z*r*ww.a.z; oo.a.w=v.a.w*r*ww.a.w;
    oo.b.x=v.b.x*r*ww.b.x; oo.b.y=v.b.y*r*ww.b.y; oo.b.z=v.b.z*r*ww.b.z; oo.b.w=v.b.w*r*ww.b.w;
    f8* po = reinterpret_cast<f8*>(o + row*128) + lane;
    asm volatile("st.global.L2::evict_last.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};" :: "l"(po), "f"(oo.a.x),"f"(oo.a.y),"f"(oo.a.z),"f"(oo.a.w),"f"(oo.b.x),"f"(oo.b.y),"f"(oo.b.z),"f"(oo.b.w) : "memory");
