    print(line)
(q,kk,wq,wk,oq,ok) = data[(2,293)]; n = 2*293*48; THR=224; R=14; grid=(2*n+R-1)//R
ks[THR]((grid,1,1),(THR,1,1), q,kk,wq,wk,oq,ok,1e-6,n); torch.cuda.synchronize()
